from abc import ABCMeta, abstractmethod

import six


@six.add_metaclass(ABCMeta)
class SignalAnalyzer(object):
    """ Stores configuration of generic signal analyzer. """

    @abstractmethod
    def __init__(self, model, ip, port):
        # type: (str, str, int) -> None
        """
        Initializes signal analyzer configuration object.
        :param model: name of signal analyzer model, i.e. KeysightN9935A
        :param ip: IP address of signal analyzer to which connection will be established
        :param port: port number on which communication with signal analyzer will be performed
        """
        self.model = model
        self.ip = ip
        self.port = port


class KeysightN9935A(SignalAnalyzer):
    """ Stores configuration of Keysight N9935A type of signal analyzer. """

    def __init__(self, ip, port=5025):
        # type: (str, int) -> None
        """
        Initializes Keysight N9935A signal analyzer configuration object.
        :param ip: IP address of signal analyzer to which connection will be established
        :param port: port number on which communication with signal analyzer will be performed; defaults to 5025
        """
        super(KeysightN9935A, self).__init__('KeysightN9935A', ip, port)


